// crc32: the CRC-32 (IEEE 802.3) of 8 MiB of generated bytes, table-driven.

fn main() {
    let n: i64 = 1 << 23;
    let data: Vec<u8> = (0..n).map(|i| ((i * 2654435761 >> 13) & 255) as u8).collect();
    let mut t = [0u32; 256];
    for (k, e) in t.iter_mut().enumerate() {
        let mut c = k as u32;
        for _ in 0..8 {
            c = if c & 1 == 1 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
        }
        *e = c;
    }
    let crc = data.iter().fold(0xFFFFFFFFu32, |c, &b| t[((c ^ b as u32) & 255) as usize] ^ (c >> 8));
    println!("{}", crc ^ 0xFFFFFFFF);
}
